const BY_EXT = new Map(ASSET_REGISTRY.map(a => [a.ext, a]));
function extOf(p: string): string { const i = p.lastIndexOf('.'); return i < 0 ? '' : p.slice(i + 1).toLowerCase(); }
export function lookupAsset(extOrPath: string): AssetInfo | undefined { return BY_EXT.get(extOrPath.toLowerCase()) ?? BY_EXT.get(extOf(extOrPath)); }
export function canEmbed(path: string): boolean { return lookupAsset(path)?.canEmbed ?? false; }
export function acceptOnDrop(path: string): boolean { return lookupAsset(path)?.acceptOnDrop ?? false; }
